    node_id character varying(36) COLLATE pg_catalog."default" NOT NULL,
    covered_on date NOT NULL,
    recorded_by uuid NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT teaching_coverage_pkey PRIMARY KEY (id),
    CONSTRAINT coverage_unique UNIQUE (offering_id, section_id, node_id)
);

